/* SPDX-License-Identifier: LGPL-3.0-or-later
 *
 * Conformance tests for fairplay_sapcore.c.
 *
 *   cc -std=c99 -Wall -Wextra fairplay_sapcore.c fairplay_sapcore_test.c -o t
 *   ./t ../../conformance
 *
 * Worth also running under sanitizers, which this port is clean under:
 *   cc -std=c99 -g -fsanitize=undefined,address fairplay_sapcore.c \
 *      fairplay_sapcore_test.c -o t
 *
 * The expected values come from the CSV files in ../../conformance, generated by the Go
 * reference in fpsapcore. Computing them here would make this a
 * test that the code agrees with itself.
 */

#include "fairplay_sapcore.h"

#include <stdio.h>
#include <string.h>

static int failures = 0;
static int checks = 0;

static void check(int ok, const char *what)
{
    checks++;
    if (!ok) {
        failures++;
        printf("FAIL: %s\n", what);
    }
}

static int parse_hex(const char *s, uint8_t *out, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        unsigned v;
        if (sscanf(s + 2 * i, "%2x", &v) != 1) {
            return 0;
        }
        out[i] = (uint8_t)v;
    }
    return 1;
}

static void to_hex(const uint8_t *b, int n, char *out)
{
    int i;
    for (i = 0; i < n; i++) {
        snprintf(out + 2 * i, 3, "%02x", b[i]);
    }
}

/* --- the three constructs most often ported wrongly --------------------- */

static void test_ring_index_underflow_boundary(void)
{
    static uint8_t x[840], y[840], z[840], w[840];
    fp_build_ring_indices(x, y, z, w);
    /* 2^32 mod 210 == 46, and 55 + 46 == 101. In C this needs no special
     * handling: unsigned wraparound is defined behaviour. */
    check(x[0] == 101, "ring x[0] should be 101, not the naive 55");
    check(x[154] == 45, "ring x[154] should be 45");
    /* From 155 on, the wrapping and non-wrapping forms agree -- which is why
     * a spot check starting past the boundary catches nothing. */
    check(x[155] == 0, "ring x[155] should be 0");
    check(x[156] == 1, "ring x[156] should be 1");
    check(w[0] == 0, "ring w never underflows");
}

static void test_rotate_or_zero_is_not_a_rotate(void)
{
    check(fp_rotate_or_zero(0xAB, 0) == 0, "a zero count must yield 0");
    check(fp_rotate_or_zero(0xAB, 0) != 0xAB, "a zero count must NOT yield the input");
    check(fp_rotate_or_zero(0x81, 1) == 0x03, "a nonzero count rotates normally");
}

static void test_wide_seed_index_is_wider_than_a_byte(void)
{
    /* If the index were masked to 8 bits these would agree everywhere. They
     * do not, and that difference is what a naive port loses. */
    int differs = 0;
    unsigned v;
    for (v = 0; v < 256u; v++) {
        uint8_t c;
        for (c = 1; c < 8; c++) {
            uint32_t wide = ((uint32_t)v << c) | ((uint32_t)v >> (8u - c));
            uint8_t masked_seed_index = (uint8_t)((wide & 0xFFu) % 21u);
            uint8_t wide_seed_index = (uint8_t)(wide % 21u);
            if (masked_seed_index != wide_seed_index) {
                differs++;
            }
        }
    }
    check(differs > 0, "masking wide_seed's index to 8 bits should change results");
}

static void test_the_all_zero_block_proves_nothing(void)
{
    /* A ring loop over an all-zero buffer stays all-zero whichever cells it
     * reads, so the all-zero vector passes even with a completely wrong index
     * table. It is the reason a smoke test is not a test here. */
    uint8_t zero[64], out_a[16], out_b[16];
    memset(zero, 0, sizeof zero);
    fp_sap_hash(zero, out_a);
    fp_sap_hash(zero, out_b);
    check(memcmp(out_a, out_b, 16) == 0, "the hash should be deterministic");
    /* Deliberately not asserting anything stronger from this one input. */
}

/* --- the corpus --------------------------------------------------------- */

static void test_sap_hash_corpus(const char *dir)
{
    char path[512], line[4096], got[64];
    FILE *f;
    int n = 0, bad = 0;

    snprintf(path, sizeof path, "%s/sap_hash.csv", dir);
    f = fopen(path, "r");
    if (!f) {
        printf("FAIL: cannot open %s -- these tests fail rather than skip "
               "without it\n", path);
        failures++;
        return;
    }
    while (fgets(line, sizeof line, f)) {
        char *comma, *want;
        uint8_t block[64], out[16];
        if (line[0] == '#' || strlen(line) < 10) {
            continue;
        }
        comma = strchr(line, ',');
        if (!comma) {
            continue;
        }
        *comma = '\0';
        want = comma + 1;
        want[strcspn(want, "\r\n")] = '\0';
        if (!parse_hex(line, block, 64)) {
            continue;
        }
        fp_sap_hash(block, out);
        to_hex(out, 16, got);
        n++;
        if (strcmp(got, want) != 0) {
            bad++;
            if (bad <= 2) {
                printf("  sap_hash mismatch\n    got  %s\n    want %s\n", got, want);
            }
        }
    }
    fclose(f);
    printf("sap_hash corpus: %d/%d\n", n - bad, n);
    check(n > 0, "the sap_hash corpus should not be empty");
    check(bad == 0, "every sap_hash vector should match");
}

static void test_bridge_corpus(const char *dir)
{
    char path[512], line[4096], got[64];
    FILE *f;
    int n = 0, bad = 0;

    snprintf(path, sizeof path, "%s/bridge_x9head.csv", dir);
    f = fopen(path, "r");
    if (!f) {
        printf("FAIL: cannot open %s\n", path);
        failures++;
        return;
    }
    while (fgets(line, sizeof line, f)) {
        char *c1, *c2, *second, *want;
        uint8_t local_sap[128], gp[128], out[20];
        if (line[0] == '#' || strlen(line) < 10) {
            continue;
        }
        c1 = strchr(line, ',');
        if (!c1) {
            continue;
        }
        *c1 = '\0';
        second = c1 + 1;
        c2 = strchr(second, ',');
        if (!c2) {
            continue;
        }
        *c2 = '\0';
        want = c2 + 1;
        want[strcspn(want, "\r\n")] = '\0';
        if (!parse_hex(line, local_sap, 128) || !parse_hex(second, gp, 128)) {
            continue;
        }
        fp_bridge_x9_head_for_sap(local_sap, gp, out);
        to_hex(out, 20, got);
        n++;
        if (strcmp(got, want) != 0) {
            bad++;
            if (bad <= 2) {
                printf("  bridge mismatch\n    got  %s\n    want %s\n", got, want);
            }
        }
    }
    fclose(f);
    printf("bridge_x9head corpus: %d/%d\n", n - bad, n);
    check(n > 0, "the bridge corpus should not be empty");
    check(bad == 0, "every bridge vector should match");
}

int main(int argc, char **argv)
{
    const char *dir = (argc > 1) ? argv[1] : "../../conformance";

    test_ring_index_underflow_boundary();
    test_rotate_or_zero_is_not_a_rotate();
    test_wide_seed_index_is_wider_than_a_byte();
    test_the_all_zero_block_proves_nothing();
    test_sap_hash_corpus(dir);
    test_bridge_corpus(dir);

    printf("%d checks, %d failures\n", checks, failures);
    return failures == 0 ? 0 : 1;
}
